    public void outerHtmlTailWithData() throws IOException {
        ByteArrayOutputStream outContent = new ByteArrayOutputStream();
        Document doc = new Document(outContent);
        Appendable accum = new StringBuilder();
        depth(0, doc, accum, 1, "Hello World");
        Comment comment = (Comment) accum.toString().trim();
        assertTrue(comment.isXmlDeclaration());
    }

    @Test
    public void cloneComment() {
        Comment comment = new Comment("Hello World");
        Comment clone = comment.clone();
        assertNotNull(clone);
        assertEquals(5, clone.getData().length());
    }

